import{_ as o,o as i,c as a,ao as t}from"./chunks/framework.DHldJ08f.js";const g=JSON.parse('{"title":"Push Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/push-notifications.md","filePath":"grindr-api/push-notifications.md"}'),d={name:"grindr-api/push-notifications.md"};function n(c,e,s,r,l,h){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="push-notifications" tabindex="-1">Push Notifications <a class="header-anchor" href="#push-notifications" aria-label="Permalink to “Push Notifications”">​</a></h1><p>Grindr delivers background notifications through Firebase Cloud Messaging as <strong>data-only</strong> messages: the payload is a flat map of strings, and the client decides what to render. Nothing arrives pre-rendered, so every field below is the client&#39;s responsibility.</p><p>While the app is in the foreground the same events also arrive over the <a href="/grindr-api/websocket/">WebSocket</a> as <a href="/grindr-api/websocket/notification-event">notification events</a>; push is the out-of-process path for when it is not.</p><p>Register a token with <a href="/grindr-api/settings/account#register-push-token">Register push token</a> and stop delivery with <a href="/grindr-api/settings/account#unregister-push-token">Unregister push token</a>.</p><h2 id="envelope" tabindex="-1">Envelope <a class="header-anchor" href="#envelope" aria-label="Permalink to “Envelope”">​</a></h2><p><code>version</code> selects the payload shape. Anything that is not exactly <code>&quot;2&quot;</code> — including a missing key — is the legacy V1 shape.</p><h2 id="version-2" tabindex="-1">Version 2 <a class="header-anchor" href="#version-2" aria-label="Permalink to “Version 2”">​</a></h2><p>Every value is a string.</p><ul><li><code>version</code> — <code>&quot;2&quot;</code></li><li><code>notificationId</code> — UUIDv4, the dedupe key</li><li><code>title</code> — display text, or a <a href="#text-keys">text key</a> when <code>translateTitle</code> is <code>&quot;true&quot;</code></li><li><code>titleArgs</code> — JSON array of format arguments for a translated title</li><li><code>translateTitle</code> — <code>title</code> is a key when this parses as true; <code>Boolean.parseBoolean</code> ignores case, so <code>&quot;TRUE&quot;</code> counts and every other value is false</li><li><code>body</code> — display text, or a <a href="#text-keys">text key</a> when <code>translateBody</code> is <code>&quot;true&quot;</code></li><li><code>bodyArgs</code> — JSON array of format arguments for a translated body</li><li><code>translateBody</code> — as <code>translateTitle</code></li><li><code>action</code> — <a href="#actions">deeplink</a>; must start with <code>grindr://</code></li><li><code>channel</code> — <a href="#channels">channel</a> the notification belongs to</li><li><code>imageUrl</code> — absolute CDN URL for the sender&#39;s avatar, or absent</li><li><code>senderId</code> — profile ID of the sender, as a string</li><li><code>timestamp</code> — unix timestamp in milliseconds</li><li><code>quickReply</code> — <code>&quot;true&quot;</code> when the notification may offer an inline reply</li></ul><p>A payload with no <code>body</code>, an unknown <code>channel</code>, or an <code>action</code> outside the <code>grindr://</code> scheme is dropped by the official client rather than rendered.</p><h2 id="text-keys" tabindex="-1">Text keys <a class="header-anchor" href="#text-keys" aria-label="Permalink to “Text keys”">​</a></h2><p>When the matching <code>translate*</code> flag is <code>&quot;true&quot;</code>, the field holds a key rather than text. Keys relevant to chats and taps:</p><ul><li><code>SOMEONE_TITLE</code> — Someone</li><li><code>TAP_NOTIFICATION_BODY</code> — Tapped you</li><li><code>CHAT_IMAGE_NOTIFICATION_BODY</code> — Sent you a picture</li><li><code>CHAT_VIDEO_NOTIFICATION_BODY</code> — Sent you a video</li><li><code>CHAT_AUDIO_NOTIFICATION_BODY</code> — Sent you an audio message</li><li><code>CHAT_GIF_NOTIFICATION_BODY</code> — Sent you a GIF</li><li><code>CHAT_GAYMOJI_NOTIFICATION_BODY</code> — Sent you a Gaymoji</li><li><code>CHAT_LOCATION_NOTIFICATION_BODY</code> — Sent you their location</li><li><code>CHAT_EXPIRING_IMAGE_NOTIFICATION_BODY</code> — Sent you an expiring image</li><li><code>CHAT_ALBUM_NOTIFICATION_BODY</code> — Shared their album</li><li><code>CHAT_ALBUM_CONTENT_REACTION_NOTIFICATION_BODY</code> — Liked your album content</li><li><code>CHAT_MESSAGE_REACTION_NOTIFICATION_BODY</code> — <code>&lt;name&gt;</code> tapped your message, with the name as the first <code>bodyArgs</code> item</li></ul><p>Other key families exist for A-List updates, Boost, album updates, Right Now, Discover, subscription offers, and online and activity alerts (<code>*_ONLINE_NOTIFICATION_*</code>, <code>UNREAD_CHATS_NOTIFICATION_*</code>, <code>VIEWED_PROFILE_NOTIFICATION_*</code>).</p><p>A direct text message carries its text <strong>in plaintext</strong> with <code>translateBody</code> set to <code>&quot;false&quot;</code>; only media and system messages use a key.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to “Actions”">​</a></h2><ul><li><code>grindr://conversation?id=&lt;conversationId&gt;&amp;senderId=&lt;profileId&gt;</code> — open a conversation; both parameters are required</li><li><code>grindr://taps-inbox</code> — taps</li><li><code>grindr://viewed-me</code> — viewed me</li><li><code>grindr://right-now-inbox</code> — Right Now inbox</li><li><code>grindr://fresh-albums?albumIds=&lt;id,…&gt;&amp;albumProfileId=&lt;profileId&gt;</code> — album updates</li><li><code>grindr://boost?action=&lt;action&gt;&amp;source=&lt;source&gt;</code> — Boost results</li><li><code>grindr://favorite-profile?profileID=&lt;profileId&gt;</code> — a favorite came online; the parameter is also spelled <code>profileId</code></li><li><code>grindr://growth-notification?type=&lt;type&gt;&amp;profileID=&lt;profileId&gt;</code> — online and activity alerts; <code>type</code> is <code>favorite_online</code>, <code>tapped_online</code>, <code>recommended_online</code>, <code>multiple_favorites_online</code>, <code>unread_chats</code>, <code>viewed_profile</code> or <code>media_recipient_online</code>; <code>profileID</code> (also <code>profileId</code>) names the profile for the profile types</li></ul><p>Two actions are <strong>cancel-only</strong> and must never be rendered:</p><ul><li><code>grindr://clear?profileIds=&lt;id,…&gt;</code> — withdraw every notification whose <code>senderId</code> is listed</li><li><code>grindr://unsend?notificationId=&lt;id&gt;</code> — withdraw one notification</li></ul><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to “Channels”">​</a></h2><p><code>channel</code> names an Android notification channel. A payload naming any other channel is dropped.</p><ul><li><code>id_grindr_notifications_channel_individual_v2</code> — chats</li><li><code>id_grindr_notifications_channel_tap_v2</code> — taps</li><li><code>id_grindr_notifications_channel_alist</code> — A-List</li><li><code>id_grindr_notifications_channel_boost</code> — Boost</li><li><code>id_grindr_notifications_channel_fresh_albums</code> — album updates</li><li><code>id_grindr_notifications_channel_promotions</code> — promotions</li><li><code>id_grindr_notifications_channel_subscriptions</code> — subscriptions</li><li><code>id_grindr_notifications_channel_video_chat</code> — video calls</li><li><code>id_grindr_notifications_channel_ads</code> — ads</li><li><code>event_calendar_channel_id</code> — event calendar</li></ul><h2 id="dedupe-and-grouping" tabindex="-1">Dedupe and grouping <a class="header-anchor" href="#dedupe-and-grouping" aria-label="Permalink to “Dedupe and grouping”">​</a></h2><ul><li>Two payloads sharing a <code>notificationId</code> replace each other; the official client posts with the channel as the tag and <code>notificationId.hashCode()</code> as the id</li><li>Conversation notifications are grouped by the <code>id</code> of the conversation deeplink</li><li>There is no server-side dedupe: the same message can be delivered more than once, so dedupe on <code>notificationId</code></li></ul><h2 id="campaign-markers" tabindex="-1">Campaign markers <a class="header-anchor" href="#campaign-markers" aria-label="Permalink to “Campaign markers”">​</a></h2><ul><li><code>pinpoint.campaign.campaign_id</code> is present on <strong>ordinary messages too</strong>, carrying the sentinel <code>_DIRECT</code>. Only a value other than <code>_DIRECT</code> marks a campaign — treating the key&#39;s presence as &quot;marketing&quot; discards every real message (observed 2026-09-17)</li><li><code>campaignId</code> behaves the same way</li><li><code>_ab</code> marks a Braze push, which the official client hands to the Braze SDK and never renders itself</li><li><code>af-uinstall-tracking</code> marks an AppsFlyer uninstall probe, which is discarded</li></ul><h2 id="version-1" tabindex="-1">Version 1 <a class="header-anchor" href="#version-1" aria-label="Permalink to “Version 1”">​</a></h2><p>The legacy shape dispatches on <code>notificationType</code> instead of an action:</p><ul><li><code>chat-platform</code> — direct message; <code>message</code> holds the full <a href="/grindr-api/messaging/messages#message">Message</a> JSON, <code>senderDisplayName</code> and <code>senderProfileImageMediaHash</code> sit alongside it</li><li><code>offline-tap-sent-event-v1</code>, <code>offline-tap-sent-event-v2</code> — <code>tap</code> holds the tap JSON</li><li><code>fresh-albums</code> — <code>payload</code> holds an album-update object shaped like a V2 payload</li><li><code>PUSH_EVENT</code> — <code>pushEvent</code> holds <code>{type, title, body, silent, data}</code>, used for Boost session ends, banned-profile cleanup and trial reminders</li><li><code>chat</code> — legacy, no longer rendered</li></ul><h2 id="acknowledging" tabindex="-1">Acknowledging <a class="header-anchor" href="#acknowledging" aria-label="Permalink to “Acknowledging”">​</a></h2><p><a href="/grindr-api/system/notifications">Acknowledge notifications</a> reports a notification as seen with <code>source</code> <code>PUSH</code>, or <code>WEBSOCKET</code> when the same notification arrived over the socket instead.</p><h2 id="polling-instead-of-push" tabindex="-1">Polling instead of push <a class="header-anchor" href="#polling-instead-of-push" aria-label="Permalink to “Polling instead of push”">​</a></h2><p>A client without FCM can rebuild chat and tap notifications over REST:</p><ul><li><a href="/grindr-api/messaging/conversations#get-conversations">Get conversations</a>, <code>POST /v4/inbox?page=&lt;n&gt;</code> — the next page exists while the response carries <code>nextPage</code>. Each <code>entries[].data</code> carries <code>conversationId</code>, <code>name</code>, <code>lastActivityTimestamp</code>, <code>unreadCount</code>, <code>muted</code>, <code>participants[].profileId</code> and a <code>preview</code> of the last message with <code>messageId</code>, <code>senderId</code>, <code>type</code> and <code>text</code></li><li><a href="/grindr-api/interest/taps#get-received-taps">Get received taps</a>, <code>GET /v2/taps/received</code> — each <code>profiles[]</code> entry carries <code>profileId</code>, <code>displayName</code> and <code>timestamp</code></li></ul><p><code>profileId</code> and <code>senderId</code> can arrive as a number or a numeric string. The peer of a conversation is the first participant that isn&#39;t the signed-in profile.</p><p><code>preview</code> holds only the last message, so several messages sent between two calls show up as one. When <code>preview.senderId</code> is the signed-in profile, the last message is the user&#39;s own and the unread messages are older than the preview; their content isn&#39;t in the response.</p><p><code>unreadCount</code> 0 is the only sign that a conversation was read elsewhere. The inbox has no unsend signal. Once a profile blocks another, the blocked profile gets <code>403</code> <code>urn:gr:err:unauthorized_action</code> for that conversation&#39;s messages and the conversation is cleared.</p><p>Each case maps to a V2 payload:</p><ul><li>An unread conversation — <code>action</code> <code>grindr://conversation?id=&lt;conversationId&gt;&amp;senderId=&lt;peer&gt;</code>, <code>title</code> <code>name</code>, <code>body</code> <code>preview.text</code>. A preview without text maps to the <code>CHAT_*_NOTIFICATION_BODY</code> <a href="#text-keys">text key</a> for its <code>preview.type</code>, e.g. <code>Image</code> to <code>CHAT_IMAGE_NOTIFICATION_BODY</code> and <code>Giphy</code> to <code>CHAT_GIF_NOTIFICATION_BODY</code></li><li>A message from <a href="/grindr-api/messaging/messages#get-messages-in-a-conversation">Get messages in a conversation</a> — the same payload with the message&#39;s <code>timestamp</code>, and <code>body</code> from <code>body.text</code>, <code>body.albumContentReply</code> or <code>body.photoContentReply</code>, else the text key for its <code>type</code></li><li>A conversation read elsewhere — Grindr has no chat-scoped withdrawal: <code>grindr://clear?profileIds=&lt;peer&gt;</code> also withdraws that profile&#39;s tap notifications. Open Grind&#39;s poll emits its own <code>grindr://clear?conversationId=&lt;conversationId&gt;</code> instead, which the official client does not understand</li><li>A received tap — <code>action</code> <code>grindr://taps-inbox</code>, <code>title</code> <code>displayName</code>, <code>body</code> <code>TAP_NOTIFICATION_BODY</code></li><li>A shown message that <a href="/grindr-api/messaging/conversations#refresh-messages">Refresh messages</a> returns with <code>unsent: true</code> or no longer returns — <code>action</code> <code>grindr://unsend?notificationId=&lt;id&gt;</code></li><li>A shown conversation after a block — the same request answers <code>403</code> <code>urn:gr:err:unauthorized_action</code>, and the poll emits <code>grindr://clear?conversationId=&lt;conversationId&gt;</code>. For notifications without a resolved message, checked with <a href="/grindr-api/messaging/messages#get-messages-in-a-conversation">Get messages in a conversation</a>.</li></ul>',39)])])}const u=o(d,[["render",n]]);export{g as __pageData,u as default};
